BURDENS={'causal':['credible identification strategy','confounding addressed','temporal ordering','robustness/sensitivity'],'predictive':['external or honest internal validation','appropriate baselines','calibration/discrimination','leakage control'],'mechanistic':['direct mechanism evidence','rival mechanisms considered','intervention or discriminating test'],'novelty':['nearest prior art searched','claim scope matched to evidence','search provenance recorded'],'generalization':['target population defined','shift/external validation considered','uncertainty reported']}
def burden_for(claim_type):return BURDENS.get((claim_type or '').lower(),['evidence directly supports claim','uncertainty bounded'])
